# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN ÇOCUKLUK YILLARINDA AİLE BÜYÜKLERİ</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Annesi Hz. Âmine (4-6 Yaş)</text>\n  <text x="125" y="95" text-anchor="middle" font-size="11" fill="#1e293b">• Sütannesi Hz. Halime\'nin yanından</text>\n  <text x="125" y="113" text-anchor="middle" font-size="11" fill="#1e293b">4 yaşında annesine döndü.</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">• 6 yaşında babası Abdullah\'ın</text>\n  <text x="125" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">kabrini ve akrabalarını ziyaret</text>\n  <text x="125" y="174" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">için Medine\'ye (Yesrib) gittiler.</text>\n  <text x="125" y="200" text-anchor="middle" font-size="11" fill="#334155">• Dönüşte Ebvâ köyünde Hz. Âmine</text>\n  <text x="125" y="218" text-anchor="middle" font-size="11" fill="#334155">vefat etti; Ümmü Eymen Mekke\'ye getirdi.</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Dedesi Abdülmuttalip (6-8 Yaş)</text>\n  <text x="350" y="95" text-anchor="middle" font-size="11" fill="#1e293b">• Mekke\'nin saygın lideri, Kâbe\'nin</text>\n  <text x="350" y="113" text-anchor="middle" font-size="11" fill="#1e293b">bakımı ve Zemzem\'in sorumlusu.</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Kâbe gölgesindeki özel minderine</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">torunu Hz. Muhammed\'i oturtur,</text>\n  <text x="350" y="174" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">onunla derin bir sevgi bağı kurardı.</text>\n  <text x="350" y="200" text-anchor="middle" font-size="11" fill="#334155">• Peygamberimiz 8 yaşındayken</text>\n  <text x="350" y="218" text-anchor="middle" font-size="11" fill="#334155">vefat etti; Ebû Talip\'e emanet bıraktı.</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Amcası Ebû Talip (8+ Yaş)</text>\n  <text x="575" y="95" text-anchor="middle" font-size="11" fill="#1e293b">• Öz babası Abdullah ile anne-baba</text>\n  <text x="575" y="113" text-anchor="middle" font-size="11" fill="#1e293b">bir öz kardeştir.</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Eşi Fâtıma binti Esed ile birlikte</text>\n  <text x="575" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">onu kendi çocuklarından üstün</text>\n  <text x="575" y="174" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">tutarak şefkatle büyüttü.</text>\n  <text x="575" y="200" text-anchor="middle" font-size="11" fill="#334155">• Peygamberimiz çobanlık ve ticaretle</text>\n  <text x="575" y="218" text-anchor="middle" font-size="11" fill="#334155">amcasının aile bütçesine destek oldu.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN AİLE BÜYÜKLERİYLE İLİŞKİLERİNDE DEĞERLER</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Çocuklukta Sergilediği Örnek Ahlak</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• Sofra Adabı ve Kanaatkârlık:</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#334155">Besmeleyle başlar, önünden yer, açgözlülük</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#334155">etmez; onun olduğu sofrada bereket olurdu.</text>\n  <text x="180" y="164" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• Çalışkanlık ve Sorumluluk:</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11" fill="#334155">Amcasının yükünü hafifletmek için Mekke\'de</text>\n  <text x="180" y="202" text-anchor="middle" font-size="11" fill="#334155">koyun güttü, Şam ticaret yolculuğuna katıldı.</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">• Doğruluk: Cahiliye kötülüklerinden uzak kaldı.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Yetişkinliğinde Gösterdiği Eşsiz Vefa</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Hz. Halime\'ye: Cübbesini altına serdi!</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Ümmü Eymen\'e: «Annemden sonra annemdir»</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11" fill="#334155">diyerek sık sık ziyaret edip ikramda bulundu.</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Ebû Talip\'e: Darlık yılında amcasının oğlu</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11" fill="#334155">Hz. Ali\'yi kendi yanına alarak bakımını üstlendi.</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">• Fâtıma binti Esed\'e: Kendi gömleğini kefen yaptı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN ÇOCUKLUK DÖNEMİ KRONOLOJİSİ (0-12 YAŞ)</text>\n  <line x1="50" y1="130" x2="650" y2="130" stroke="#3b82f6" stroke-width="4"/>\n\n  <circle cx="90" cy="130" r="14" fill="#2563eb"/>\n  <text x="90" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">571</text>\n  <text x="90" y="85" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">Doğumu (Mekke)</text>\n  <text x="90" y="102" text-anchor="middle" font-size="10" fill="#475569">Fil Yılı / 20 Nisan</text>\n\n  <circle cx="220" cy="130" r="14" fill="#16a34a"/>\n  <text x="220" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">0-4</text>\n  <text x="220" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Sütanne Yılları</text>\n  <text x="220" y="185" text-anchor="middle" font-size="10" fill="#475569">Hz. Halime (Sa\'d Yurdu)</text>\n\n  <circle cx="350" cy="130" r="14" fill="#db2777"/>\n  <text x="350" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">6 Yaş</text>\n  <text x="350" y="85" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Medine Yolculuğu</text>\n  <text x="350" y="102" text-anchor="middle" font-size="10" fill="#475569">Ebvâ\'da Hz. Âmine\'nin vefatı</text>\n\n  <circle cx="480" cy="130" r="14" fill="#d97706"/>\n  <text x="480" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">8 Yaş</text>\n  <text x="480" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Dedesinin Himayesi</text>\n  <text x="480" y="185" text-anchor="middle" font-size="10" fill="#475569">Abdülmuttalip\'in vefatı</text>\n\n  <circle cx="610" cy="130" r="14" fill="#7c3aed"/>\n  <text x="610" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">8-12+</text>\n  <text x="610" y="85" text-anchor="middle" font-size="11" font-weight="bold" fill="#6d28d9">Ebû Talip\'in Evi</text>\n  <text x="610" y="102" text-anchor="middle" font-size="10" fill="#475569">Çobanlık ve Şam yolculuğu</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
